(function(){
  'use strict';
  const P=EquipmentPuzzle,M=TeamBuildingLab,$=id=>document.getElementById(id),key='spacologyEquipmentPuzzleV1';
  const teams={hypercarry:['Silen','Aurel','Ekene','Roonie','Nahana'],break:['Wren','Quill','Aurel','Roonie','Nahana'],counter:['Reva','Ilka','Latch','Roonie','Nahana'],dot:['Nour','Spore','Redcap','Latch','Nahana']};
  let state=P.create(),selected=0,rotation=0,undo=[],history=[],feedback={},last=null,seed=41;
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const message=s=>{$('puzzleMessage').textContent=s;};
  function save(){try{localStorage.setItem(key,JSON.stringify({state,history,feedback,seed}));}catch{message('Browser storage unavailable; export to keep this puzzle.');}}
  function changed(type){history.push({type,scenario:state.scenario,owner:state.owner,placements:state.placements.map(p=>({...p})),at:new Date().toISOString()});last=null;$('puzzleReport').innerHTML='<p class="muted small">Arrangement changed. Test it to see what activates in combat.</p>';save();render();}
  function pushUndo(){undo.push(JSON.parse(JSON.stringify(state)));if(undo.length>40)undo.shift();}
  function mini(type){const shape=P.cells(P.pieces[type].shape);return `<span class="mini-shape" style="--piece-color:${P.pieces[type].color}">${shape.map(([x,y])=>`<i style="grid-column:${x+1};grid-row:${y+1}"></i>`).join('')}</span>`;}
  function render(){
    const problem=P.scenarios[state.scenario],team=teams[problem.engine],result=P.evaluate(state,M.roster[state.owner]);
    $('puzzle').value=state.scenario;$('wearer').innerHTML=team.map(id=>`<option value="${id}" ${id===state.owner?'selected':''}>${id} · ${M.roster[id].role}</option>`).join('');
    $('problemName').textContent=problem.name;$('problemGoal').textContent=problem.goal;$('problemEnemy').textContent=M.encounters[problem.encounter].weakness;
    $('powerBudget').textContent=`${result.usedCells} / ${16-state.blocked.length} spaces · ${result.draw} / ${result.supply} power`;
    $('board').innerHTML=Array.from({length:16},(_,i)=>{const x=i%4,y=Math.floor(i/4),blocked=state.blocked.some(p=>p[0]===x&&p[1]===y),placed=state.placements.find(p=>P.footprint(state,p).some(q=>q[0]===x&&q[1]===y)),piece=placed?P.pieces[state.inventory[placed.index]]:null;return `<button class="board-cell ${blocked?'blocked':''} ${piece?'filled':''} ${placed&&result.powered.includes(placed.index)?'powered':''} ${placed&&placed.index===selected?'selected':''}" data-cell="${i}" ${blocked?'disabled':''} ${piece?`style="--piece-color:${piece.color}"`:''} aria-label="Row ${y+1}, column ${x+1}${blocked?', blocked':piece?', '+piece.name:', empty'}">${blocked?'×':piece?piece.short:'·'}</button>`;}).join('');
    $('parts').innerHTML=state.inventory.map((type,i)=>`<button class="part ${i===selected?'active':''} ${state.placements.some(p=>p.index===i)?'installed':''}" data-piece="${i}">${mini(type)}<div><b>${P.pieces[type].name} ${type==='cell'?'+3 power':''}</b><span>${state.placements.some(p=>p.index===i)?'Installed · select to move':'Loose · select to place'}</span></div></button>`).join('');
    const piece=P.pieces[state.inventory[selected]];$('selection').textContent=piece?`${piece.name} · rotation ${rotation*90}° · ${piece.text}`:'Select a component.';
    $('removePiece').disabled=!state.placements.some(p=>p.index===selected);$('rotatePiece').disabled=!piece;$('undoPuzzle').disabled=!undo.length;
    $('mechanisms').innerHTML=result.status.map(s=>{const r=P.recipes.find(v=>v.id===s.id);return `<div class="mechanism ${s.active?'on':''}" data-mechanism="${r.id}"><div class="section-title"><b>${r.name}</b><span class="status">${s.active?'ACTIVE':esc(s.reason)}</span></div><p>${r.parts.map(id=>P.pieces[id].name).join(' + ')} · ${r.draw} power</p><p>${r.text}</p><button data-priority="${r.id}" ${state.priority[0]===r.id?'disabled':''}>Give priority</button></div>`;}).join('');
    $('puzzleTeam').textContent='Team: '+team.join(' · ')+'. Carry / protection recipient: '+M.engines[problem.engine].starter+'.';$('puzzleAdvance').checked=state.enemyAdvance;
    $('puzzleRating').value=feedback.rating||'';$('puzzleNotes').value=feedback.notes||'';$('testSeed').value=seed;
  }
  function ghost(index){document.querySelectorAll('.ghost-ok,.ghost-bad').forEach(c=>c.classList.remove('ghost-ok','ghost-bad'));if(selected===null)return;const p={index:selected,x:index%4,y:Math.floor(index/4),rotation},bad=P.validate(state,p);P.footprint(state,p).forEach(([x,y])=>{if(x>=0&&y>=0&&x<4&&y<4)$('board').querySelector(`[data-cell="${y*4+x}"]`)?.classList.add(bad?'ghost-bad':'ghost-ok');});}
  function test(){const problem=P.scenarios[state.scenario],s=M.create({engine:problem.engine,sandbox:true,seed});s.team=teams[problem.engine];s.carry=M.engines[problem.engine].starter;s.recipient=s.carry;s.enemyAdvance=state.enemyAdvance;const enabled=P.evaluate(state,M.roster[state.owner]);const opts={seed,encounter:M.encounters[problem.encounter]};const bare=M.fight(s,opts),working=M.fight(s,{...opts,circuits:{[state.owner]:enabled.effects}});last={bare,working,evaluation:enabled};history.push({type:'test',scenario:state.scenario,owner:state.owner,placements:state.placements.map(p=>({...p})),active:enabled.status.filter(v=>v.active).map(v=>v.id),bare,working});save();
    $('puzzleReport').innerHTML=`<div class="mini-result"><b>${working.reason} · ${working.av} AV</b><p class="trigger-note">${working.metrics.circuitTriggers} actual mechanism triggers</p><p>${enabled.status.some(s=>s.active)?'An active mechanism can still be a poor match for this enemy. Compare what it actually triggered.':'Nothing is active yet. Inspect missing parts, contact, power and wearer requirements above.'}</p></div><div class="compare-table"><table><thead><tr><th>Same team / seed</th><th>Disconnected</th><th>As arranged</th></tr></thead><tbody>${[['Result',bare.reason,working.reason],['Elapsed AV',bare.av,working.av],['Direct damage',bare.metrics.direct,working.metrics.direct],['Poison damage',bare.metrics.dot,working.metrics.dot],['Ultra-break',bare.metrics.ultra,working.metrics.ultra],['Retaliation',bare.metrics.retaliation,working.metrics.retaliation],['Aether-starved actions',bare.metrics.starved,working.metrics.starved],['Crew down',bare.metrics.deaths,working.metrics.deaths]].map(([name,a,b])=>`<tr><td>${name}</td><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div><details><summary>Mechanism events</summary><ol class="logs">${working.log.filter(l=>/recycles|widens|recovers Aether|through its mechanism|after recovery/.test(l.text)).map(l=>`<li>${l.av} AV · ${esc(l.text)}</li>`).join('')||'<li>No qualifying events this fight.</li>'}</ol></details>`;message('Test complete. Rearrange freely, then compare again.');}
  $('puzzle').innerHTML=P.scenarios.map((p,i)=>`<option value="${i}">${i+1} · ${p.name}</option>`).join('');
  try{const old=JSON.parse(localStorage.getItem(key));if(old?.state?.version===1&&P.scenarios[old.state.scenario]){const canonical=P.create(old.state.scenario);if(JSON.stringify(old.state.inventory)===JSON.stringify(canonical.inventory)&&JSON.stringify(old.state.blocked)===JSON.stringify(canonical.blocked)&&teams[P.scenarios[old.state.scenario].engine].includes(old.state.owner)&&Array.isArray(old.state.placements)&&old.state.placements.every(p=>!P.validate(old.state,p))&&new Set(old.state.placements.map(p=>p.index)).size===old.state.placements.length&&Array.isArray(old.state.priority)&&old.state.priority.length===P.recipes.length&&new Set(old.state.priority).size===P.recipes.length&&old.state.priority.every(id=>P.recipes.some(r=>r.id===id))){state={...canonical,...old.state,width:4,height:4};history=Array.isArray(old.history)?old.history:[];feedback=old.feedback||{};seed=Number(old.seed)||41;}}}catch{message('Started a fresh board.');}
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.piece!==undefined){selected=Number(b.dataset.piece);rotation=state.placements.find(p=>p.index===selected)?.rotation||0;render();}
    if(b.dataset.cell!==undefined){const i=Number(b.dataset.cell),existing=state.placements.find(p=>P.footprint(state,p).some(([x,y])=>y*4+x===i));if(existing&&existing.index!==selected){selected=existing.index;rotation=existing.rotation;render();message('Selected installed part. Tap an empty anchor to move, or remove it.');return;}const p={index:selected,x:i%4,y:Math.floor(i/4),rotation},error=P.validate(state,p);if(error){message(error);history.push({type:'rejected',reason:error});save();return;}pushUndo();P.place(state,p);changed('place');message('Placed. Check which mechanism is active.');}
    if(b.dataset.priority){pushUndo();state.priority=[b.dataset.priority,...state.priority.filter(id=>id!==b.dataset.priority)];changed('priority');}
  });
  $('board').addEventListener('pointerover',e=>{const c=e.target.closest('[data-cell]');if(c)ghost(Number(c.dataset.cell));});$('board').addEventListener('focusin',e=>{if(e.target.dataset.cell!==undefined)ghost(Number(e.target.dataset.cell));});$('board').addEventListener('pointerleave',()=>document.querySelectorAll('.ghost-ok,.ghost-bad').forEach(c=>c.classList.remove('ghost-ok','ghost-bad')));
  $('rotatePiece').onclick=()=>{rotation=(rotation+1)%4;render();message('Rotated. Tap an anchor to place or move.');};$('removePiece').onclick=()=>{pushUndo();P.remove(state,selected);changed('remove');};$('undoPuzzle').onclick=()=>{if(undo.length){state=undo.pop();changed('undo');}};
  $('wearer').onchange=e=>{pushUndo();state.owner=e.target.value;changed('wearer');};$('puzzle').onchange=e=>{state=P.create(Number(e.target.value));selected=0;rotation=0;undo=[];changed('problem');};$('resetPuzzle').onclick=()=>{pushUndo();state=P.create(state.scenario);selected=0;rotation=0;changed('reset');};$('puzzleAdvance').onchange=e=>{state.enemyAdvance=e.target.checked;changed('enemy-advance');};$('testSeed').onchange=e=>{seed=(Number(e.target.value)>>>0)||41;changed('seed');};$('testPuzzle').onclick=test;
  ['puzzleRating','puzzleNotes'].forEach(id=>$(id).oninput=()=>{feedback[id==='puzzleRating'?'rating':'notes']=$(id).value;save();});
  $('exportPuzzle').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({state,seed,history,feedback,last},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='equipment-puzzle-playtest.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  render();
})();
